const body = $input.item.json.body || $input.item.json || {};
const context = body.context || body.message || '';
const tone = body.tone || 'professional';
const recipient = body.recipient || 'colleague';

const systemPrompt = `You are HomeBot Email Assistant. Draft professional, well-structured emails based on the user's context.

Guidelines:
- Tone: ${tone}
- Recipient type: ${recipient}
- Include a clear subject line
- Keep paragraphs short (2-3 sentences max)
- End with an appropriate sign-off
- Be concise but thorough

Format your response as:
**Subject:** [subject line]

---

[email body]

---

*Suggested sign-off options: [2-3 options]*`;

return {
  json: {
    model: 'qwen2.5:7b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Draft an email with this context: ${context}` }
    ],
    stream: false
  }
};

const ollamaRes = $input.item.json;
const content = ollamaRes.message?.content || ollamaRes.response || 'Unable to draft email';
return {
  json: {
    output: content,
    data: { assistant: { role: 'assistant', content } }
  }
};
